import type { Theme } from "../source/theme.ts";
import { nativeFamily } from "./native-fonts.ts";

const header =
  "/* Generated by @ome-labs/tokens from tokens/*.json: edit the JSON, then run `pnpm build`. */";

/**
 * The theme for Uniwind (Tailwind 4 on React Native). Uniwind reads theme colours from `@layer theme`
 * with one `@variant` per theme, and every theme must declare the same names. React Native needs
 * absolute line heights and letter spacing, and one font family per weight.
 */
export function nativeCss(theme: Theme): string {
  const colors = (mode: "light" | "dark") =>
    theme.semantic.map((color) => `      --color-${color.utility}: ${color[mode]};`).join("\n");

  const typeUtilities = theme.text.map((style) =>
    [
      `@utility type-${style.name} {`,
      `  font-family: ${nativeFamily(style)};`,
      `  font-size: ${style.size}px;`,
      `  line-height: ${Math.round(style.size * style.lineHeight)}px;`,
      `  letter-spacing: ${Number((style.size * style.letterSpacing).toFixed(2))}px;`,
      ...(style.uppercase ? ["  text-transform: uppercase;"] : []),
      "}",
    ].join("\n"),
  );

  return [
    header,
    "",
    "@layer theme {",
    "  :root {",
    "    @variant light {",
    colors("light"),
    "    }",
    "    @variant dark {",
    colors("dark"),
    "    }",
    "  }",
    "}",
    "",
    "@theme {",
    "  --font-display: InstrumentSerif-Regular;",
    "  --font-sans: Inter-Regular;",
    "  --font-sans-medium: Inter-Medium;",
    "  --font-sans-semibold: Inter-SemiBold;",
    "  --font-sans-bold: Inter-Bold;",
    "  --font-mono: JetBrainsMono-Regular;",
    "  --font-mono-medium: JetBrainsMono-Medium;",
    ...theme.text.map((style) => `  --text-${style.name}: ${style.size}px;`),
    "  --spacing: 4px;",
    ...theme.radius.map((radius) => `  --radius-${radius.name}: ${radius.px}px;`),
    ...theme.control.map((control) => `  --height-control-${control.name}: ${control.px}px;`),
    "}",
    "",
    ...typeUtilities,
    "",
  ].join("\n");
}
